@Mod.EventBusSubscriber(modid=Thaumcraft.MODID)
public final class FinishProbe {
 static final BlockPos Q=new BlockPos(1600,205,8);static ServerPlayer p;static int ticks;static boolean done;
 static boolean mode(){var mode=System.getProperty("thaumcraft.thaumaturgyProbe","");return mode.equals("finish-write")||mode.equals("finish-read");}
 static ServerPlayer player(net.minecraft.server.MinecraftServer server,UUID id){return new ServerPlayer(server,server.overworld(),new GameProfile(id,"FinishProbe"),ClientInformation.createDefault()){@Override public void sendSystemMessage(Component c,boolean o){}@Override protected ItemCooldowns createItemCooldowns(){return new ItemCooldowns();}};}
 static GolemBuilder press(ServerPlayer p,BlockPos at,Direction face){var l=p.level();var parts=GolemPress.parts(at,face);var blocks=List.of(Blocks.IRON_BARS,Blocks.CAULDRON,Blocks.ANVIL,thaumcraft.content.SimpleContent.BLOCKS.get("table_stone").get());for(var q:BlockPos.betweenClosed(at.offset(-2,-1,-2),at.offset(2,-1,2)))l.setBlockAndUpdate(q,Blocks.STONE.defaultBlockState());l.setBlockAndUpdate(at,Blocks.PISTON.defaultBlockState().setValue(PistonBaseBlock.FACING,Direction.UP));for(int i=0;i<4;i++)l.setBlockAndUpdate(parts.get(i),blocks.get(i).defaultBlockState());p.setPos(Vec3.atCenterOf(at));var salis=new ItemStack(thaumcraft.crafting.ArcaneContent.SALIS.get());p.setItemInHand(InteractionHand.MAIN_HAND,salis);var result=salis.getItem().useOn(new net.minecraft.world.item.context.UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(at),Direction.UP,at,false)));check(result==InteractionResult.SUCCESS&&salis.isEmpty(),"Native salis press assembly failed "+face);check(GolemPress.intact(l,at),"Assembled press incomplete");return (GolemBuilder)l.getBlockEntity(at);}
 static void patterns(ServerPlayer p,BlockPos at){var l=p.level();l.setBlockAndUpdate(at.below(),Blocks.CHEST.defaultBlockState());l.setBlockAndUpdate(at.above(),Blocks.CHEST.defaultBlockState());l.setBlockAndUpdate(at,GolemContent.PATTERN.get().defaultBlockState());var machine=(PatternCrafter)l.getBlockEntity(at);var in=(ChestBlockEntity)l.getBlockEntity(at.above());var out=(ChestBlockEntity)l.getBlockEntity(at.below());AuraManager.addVis(l,at,100);
  Item[] input={Items.GOLD_NUGGET,Items.IRON_INGOT,Items.OAK_PLANKS,Items.OAK_PLANKS,Items.OAK_PLANKS,Items.COBBLESTONE,Items.DIAMOND,Items.IRON_INGOT,Items.OAK_PLANKS,Items.OAK_PLANKS};Item[] output={Items.GOLD_INGOT,Items.IRON_NUGGET,Items.OAK_PRESSURE_PLATE,Items.STICK,Items.CRAFTING_TABLE,Items.COBBLESTONE_SLAB,Items.AIR,Items.IRON_BARS,Items.OAK_DOOR,Items.CHEST};int[] amounts={1,9,1,4,1,6,0,16,3,1};
  for(int pattern=0;pattern<10;pattern++){while(machine.pattern()!=pattern)machine.cycle();in.clearContent();out.clearContent();in.setItem(0,new ItemStack(input[pattern],GolemPatterns.slots(pattern).length));float before=AuraManager.get(l,at).vis()+machine.power();boolean crafted=machine.craft();check(crafted==(pattern!=6),"Wrong native pattern result "+pattern);if(crafted){check(in.isEmpty()&&GolemClient.count(out,output[pattern])==amounts[pattern],"Native recipe consumed/result mismatch "+pattern);check(Math.abs(AuraManager.get(l,at).vis()+machine.power()-(before-1))<.01,"Craft must pay one vis including reserve");}else check(in.getItem(0).getCount()==3&&out.isEmpty(),"Invalid pattern consumed items");}
  while(machine.pattern()!=0)machine.cycle();in.clearContent();in.setItem(0,new ItemStack(Items.GOLD_NUGGET,9));for(int i=0;i<out.getContainerSize();i++)out.setItem(i,new ItemStack(Items.COBBLESTONE,64));float fuel=machine.power();check(!machine.craft()&&in.getItem(0).getCount()==9&&machine.power()==fuel,"Blocked output consumed material/fuel");out.clearContent();l.setBlockAndUpdate(at.east(),Blocks.REDSTONE_BLOCK.defaultBlockState());check(!machine.craft()&&in.getItem(0).getCount()==9,"Powered crafter worked");l.removeBlock(at.east(),false);
  // Resume after pause and leave a nonempty fuel reserve for the restart check.
  while(machine.pattern()!=1)machine.cycle();in.clearContent();in.setItem(0,new ItemStack(Items.IRON_INGOT));check(machine.craft()&&GolemClient.count(out,Items.IRON_NUGGET)==9,"Crafter did not resume after pause");in.clearContent();in.setItem(0,new ItemStack(Items.IRON_INGOT));check(machine.craft(),"Second craft failed");in.clearContent();Thaumcraft.LOGGER.info("FINISH_PATTERNS_OK: ten layouts, nine native valid recipes, one invalid case, exact vis, blocked output and redstone");
 }
 static void options(ServerPlayer p){var l=p.level();var provider=LogisticsClient.chestSeal(p,SealKind.PROVIDER,Q.north(5));p.setPos(Vec3.atCenterOf(provider.getBlockPos()));var in=(ChestBlockEntity)l.getBlockEntity(provider.support());in.setItem(0,new ItemStack(Items.EMERALD,9));check(provider.edit(p,27)&&provider.edit(p,28)&&provider.extractionLimit(new ItemStack(Items.EMERALD),8)==1,"Provider leave/single controls failed");in.setItem(0,new ItemStack(Items.EMERALD));check(provider.extractionLimit(new ItemStack(Items.EMERALD),8)==0,"Provider extracted last item");provider.setChanged();
  var empty=LogisticsClient.chestSeal(p,SealKind.EMPTY_ADVANCED,Q.north(8));p.setPos(Vec3.atCenterOf(empty.getBlockPos()));empty.sample(0,new ItemStack(Items.GOLD_INGOT));empty.sample(8,new ItemStack(Items.EMERALD));var inv=(ChestBlockEntity)l.getBlockEntity(empty.support());inv.setItem(0,new ItemStack(Items.GOLD_INGOT,7));inv.setItem(1,new ItemStack(Items.EMERALD,7));check(empty.edit(p,27)&&empty.edit(p,29)&&empty.acceptsExtraction(new ItemStack(Items.GOLD_INGOT))&&!empty.acceptsExtraction(new ItemStack(Items.EMERALD)),"Cyclic selection failed");empty.extracted(new ItemStack(Items.GOLD_INGOT));check(empty.acceptsExtraction(new ItemStack(Items.EMERALD))&&!empty.acceptsExtraction(new ItemStack(Items.GOLD_INGOT)),"Cyclic cursor did not advance");empty.setChanged();
  var fill=LogisticsClient.chestSeal(p,SealKind.FILL_ADVANCED,Q.south(5));p.setPos(Vec3.atCenterOf(fill.getBlockPos()));fill.sample(8,new ItemStack(Items.DIAMOND));fill.amounts[8]=5;check(fill.edit(p,30)&&fill.fillLimit(new ItemStack(Items.DIAMOND,20))==0,"Existing-only accepted absent type");((ChestBlockEntity)l.getBlockEntity(fill.support())).setItem(0,new ItemStack(Items.DIAMOND,3));check(fill.fillLimit(new ItemStack(Items.DIAMOND,20))==2,"Fill quota failed");fill.setChanged();
  var guest=player(l.getServer(),UUID.fromString("11c9f2d3-62b6-45f7-9755-402729fe335e"));var worker=new WorkerGolem(GolemContent.GOLEM.get(),l);worker.configure(guest,GolemDesign.BASIC,provider.getBlockPos(),0);check(!provider.claim(worker),"Private seal shared implicitly");p.setPos(Vec3.atCenterOf(provider.getBlockPos()));check(provider.edit(p,36)&&provider.claim(worker),"Explicit shared seal unavailable");provider.release(worker);check(provider.edit(p,36)&&!provider.claim(worker),"Relocking did not deny guest");
  var guard=GolemProbe.seal(p,SealKind.GUARD_ADVANCED,Q.south(8));p.setPos(Vec3.atCenterOf(guard.getBlockPos()));check(guard.edit(p,34)&&guard.targets()==3&&guard.edit(p,35)&&guard.targets()==7,"Independent guard categories failed");guard.setChanged();
  var harvest=GolemProbe.seal(p,SealKind.HARVEST,Q.east(3));p.setPos(Vec3.atCenterOf(harvest.getBlockPos()));check(harvest.edit(p,32),"Harvest provision rejected");harvest.replants.put(Q.east(4),Blocks.WHEAT.defaultBlockState());l.setBlockAndUpdate(Q.east(4).below(),Blocks.FARMLAND.defaultBlockState());harvest.setChanged();
  Thaumcraft.LOGGER.info("FINISH_OPTIONS_OK: keep-one/single/cycle/existing/quota, shared permission, mixed targets and seed queue");
 }
 static void cocoa(ServerPlayer p){var l=p.level();var harvest=GolemProbe.seal(p,SealKind.HARVEST,Q.south(12));for(var face:Direction.Plane.HORIZONTAL){var at=Q.south(12).relative(face);l.setBlockAndUpdate(at,Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(at.relative(face),Blocks.JUNGLE_LOG.defaultBlockState());var desired=Blocks.COCOA.defaultBlockState().setValue(CocoaBlock.FACING,face);harvest.replants.put(at,desired);var worker=new WorkerGolem(GolemContent.GOLEM.get(),l);worker.configure(p,new GolemDesign(3,1,1,0),at.above(),0);worker.cargo.setItem(0,new ItemStack(Items.COCOA_BEANS));check(GolemCrops.plant(l,p,worker,harvest,at)&&worker.cargo.isEmpty()&&l.getBlockState(at).getValue(CocoaBlock.FACING)==face,"Native cocoa replant failed "+face);}l.removeBlock(harvest.getBlockPos(),false);Thaumcraft.LOGGER.info("FINISH_COCOA_OK: queued native bean planting consumes one item on all four support faces");}
 @SubscribeEvent public static void start(ServerStartedEvent e){if(!mode())return;var l=e.getServer().overworld();for(int x=99;x<=103;x++)for(int z=-1;z<=1;z++)l.setChunkForced(x,z,true);l.setChunkForced(87,0,true);p=player(e.getServer(),AreaProbe.OWNER);knowledge(p);}
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(!mode()||done||++ticks<80)return;var l=p.level();boolean write=System.getProperty("thaumcraft.thaumaturgyProbe").equals("finish-write");MatchingRules.verify();
  if(write){for(var face:Direction.Plane.HORIZONTAL)press(p,Q.east(8+face.ordinal()*5),face);var brokenAt=Q.east(8+Direction.WEST.ordinal()*5);var broken=GolemPress.parts(brokenAt,Direction.WEST).get(0);l.destroyBlock(broken,true);check(l.getBlockState(brokenAt).is(Blocks.PISTON),"Breaking press part did not restore core");for(var other:GolemPress.parts(brokenAt,Direction.WEST))if(!other.equals(broken))check(!(l.getBlockEntity(other) instanceof PressPart),"Press part remained after dismantle");var core=(GolemBuilder)l.getBlockEntity(Q.east(8+Direction.NORTH.ordinal()*5));core.draft=new GolemDesign(5,4,4,3,3);p.setPos(Vec3.atCenterOf(core.getBlockPos()));for(var entry:core.draft.components().entrySet())p.getInventory().add(new ItemStack(net.minecraft.core.registries.BuiltInRegistries.ITEM.getValue(net.minecraft.resources.Identifier.parse(entry.getKey())),entry.getValue()));check(core.start(p),"Native assembled press refused paid design");check(core.insert("machina",Direction.DOWN,false),"Assembled press refused machina");patterns(p,Q.west(5));options(p);Thaumcraft.LOGGER.info("FINISH_WRITE_OK: four press orientations, salis payment, reversible dismantle, paid job, pattern fuel and complete seal settings");}
  else{var core=(GolemBuilder)l.getBlockEntity(Q.east(8+Direction.NORTH.ordinal()*5));check(core!=null&&GolemPress.intact(l,core.getBlockPos())&&(!core.working()||core.remaining()==core.total()-1),"Multiblock paid job changed after restart");while(core.working())check(core.insert("machina",Direction.DOWN,false),"Resumed press refused machina");check(core.output.getItem(0).get(GolemContent.DESIGN.get()).equals(new GolemDesign(5,4,4,3,3)),"Assembled press resumed wrong design");var provider=(SealEntity)l.getBlockEntity(Q.north(5).west());check(provider.leaveOne&&provider.single&&!provider.shared,"Provider options changed");var empty=(SealEntity)l.getBlockEntity(Q.north(8).west());check(empty.cycle&&empty.leaveOne&&empty.acceptsExtraction(new ItemStack(Items.EMERALD)),"Cyclic cursor not saved");var fill=(SealEntity)l.getBlockEntity(Q.south(5).west());check(fill.existingOnly&&fill.amounts[8]==5,"Fill policy not saved");var guard=(SealEntity)l.getBlockEntity(Q.south(8));check(guard.targets()==7,"Mixed guard categories not saved");var crop=(SealEntity)l.getBlockEntity(Q.east(3));check(crop.harvestProvision&&crop.replant&&crop.replants.get(Q.east(4)).is(Blocks.WHEAT),"Seed queue not saved");var crafter=(PatternCrafter)l.getBlockEntity(Q.west(5));check(crafter!=null&&crafter.pattern()==1&&crafter.crafts()==11&&crafter.power()>0&&crafter.power()<5,"Crafter counters/fuel not saved");var old=(SealEntity)l.getBlockEntity(MatchingProbe.Q);check(old!=null&&old.matchTags&&old.matchMod&&!old.matchDamage&&!old.shared,"Actual port.28 seal changed");cocoa(p);Thaumcraft.LOGGER.info("FINISH_RESTART_OK: multiblock restoration/job, physical output, settings/cursor/seed queue/fuel and actual port.28 data preserved");}
  done=true;e.server().halt(false);
 }
}
